// Actual native HTTP failure, runtime repair and durable producer/consumer graph.
import assert from 'node:assert/strict';
import {writeFile} from 'node:fs/promises';
import {FileNeuraleseStore} from '../../dist/neuralese/node-block-store.js';
import {neuraleseServerModelTurn} from '../../dist/model/neuralese-server.js';
import {NativeToolAgent} from '../../dist/native/agent.js';
import {session as open} from '../support/natlang.mjs';
import {ModelTurnRecorder,setRecorderSource} from '../../dist/native/model-recording.js';
import {nativeStateConsumerFromInfo} from '../../dist/native/neuralese.js';
const [endpoint,archive]=process.argv.slice(2);
// These manually opened invocations belong to one actual execution graph.
const sharedEpisodeBudget = { used: 0 };
const info=await fetch(endpoint+'/v1/neuralese/info').then(r=>r.json());
const store=await FileNeuraleseStore.open(archive,{residentBytes:0});
const neuralese={store,dialect:info.dialects[0],nativeStateConsumer:nativeStateConsumerFromInfo(info)};
const recorder=new ModelTurnRecorder();setRecorderSource(()=>recorder);
const server=neuraleseServerModelTurn({endpoint,model:'native-fixture',store});
const driver=Object.assign(request=>server({...request,max_tokens:8}),{neuralese:true,decide:server.decide});
const child=open({type:'() => Neuralese<string>',instructions:'Produce a useful memo.'},{neuralese, sharedEpisodeBudget}).session;
await new NativeToolAgent(driver,{maxTurns:3,temperature:.8,neuralese}).run(child);
assert.ok(child.lam.return?.$neuralese,JSON.stringify(child.lam));
const id=child.lam.return.$neuralese.id;
assert.ok(await store.getNativeState(id));
const parent=open({type:'(memo: Neuralese<string>) => string',instructions:'Consume the child memo.',args:{memo:child.lam.return}},{neuralese, sharedEpisodeBudget}).session;
await new NativeToolAgent(driver,{maxTurns:3,temperature:.8,neuralese}).run(parent);
assert.equal(parent.lam.return,'t7');
const turns=recorder.nativeTurns();assert.equal(turns.length,3);
assert.equal(turns[0].native.sampling.protocol_failure.code,'neuralese-native-state-close');
assert.equal(turns[0].native.sampling.writes.length,1);
assert.ok(turns[1].messages.some(message=>typeof message.content==='string'&&message.content.includes('incomplete or misplaced native-state delimiter')));
for(const turn of turns)for(const write of turn.native.sampling.writes)assert.ok(await store.getNativeState(write.state_id));
const graph=[...recorder.graphNodes.values()];
assert.equal(graph.filter(node=>node.kind==='model_turn').length,3);
await writeFile(archive+'/recording.json',JSON.stringify({turns,graph}));
console.log(JSON.stringify({recovered:true,state_id:id}));
